import React, { useState, useCallback } from 'react';
import { marked } from 'marked';
import { parseTemplate, extractFieldNamesFromTemplate, generateOutput, generatePlainOutput, toPlainText } from '../utils/templateProcessor';
import { bitable, FieldType } from '@lark-base-open/js-sdk';

const defaultTemplate = `**[数据中心]：**
[需求FLOW]-[任务内容] [上线类型]：
> [系统]<font color='grey-500'>*（[项目名称]）*</font>- [开发负责人]`;

const FeishuPlugin: React.FC = () => {
  const [appId, setAppId] = useState('');
  const [appSecret, setAppSecret] = useState('');
  const [appToken, setAppToken] = useState('');
  const [tableId, setTableId] = useState('');
  const [template, setTemplate] = useState(defaultTemplate);
  const [result, setResult] = useState('');
  const [pureResult, setPureResult] = useState('');
  
  // 添加用于存储用户编辑后内容的状态
  const [editableResult, setEditableResult] = useState('');
  const [editablePureResult, setEditablePureResult] = useState('');
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState('');
  const [previewHtml, setPreviewHtml] = useState('');
  const [resultPreviewHtml, setResultPreviewHtml] = useState('');
  const [copied, setCopied] = useState(false);
  const [copiedPure, setCopiedPure] = useState(false);
  const [activeTab, setActiveTab] = useState<'styled' | 'plain'>('styled');
  const [hasGenerated, setHasGenerated] = useState(false);

  const updatePreview = useCallback(async (text: string) => {
    const html = await marked(text);
    setPreviewHtml(html);
  }, []);

  React.useEffect(() => {
    updatePreview(template);
  }, [template, updatePreview]);

  React.useEffect(() => {
    const run = async () => {
      if (!result) {
        setPureResult('');
        setResultPreviewHtml('');
        setEditableResult('');
        setEditablePureResult('');
        return;
      }
      
      // 确保editableResult被正确设置
      setEditableResult(result);
      
      // 直接使用plainOutput作为纯净版结果，不再重新处理
      // 注意：这里不再需要额外处理，因为generatePlainOutput已经处理了开发负责人姓名
      
      const html = await marked(result);
      setResultPreviewHtml(html);
    };
    run();
  }, [result]);

  const handleCopyResult = async () => {
  try {
    if (!editableResult) return;  // 已更新为 editableResult

    let copySuccess = false;

    // 尝试现代 Clipboard API
    if (navigator.clipboard?.writeText) {
      try {
        await navigator.clipboard.writeText(editableResult); // 修改为 editableResult
        copySuccess = true;
      } catch {
        // 静默失败，继续尝试其他方法
      }
    }

    // 尝试传统 execCommand
    if (!copySuccess) {
      try {
        const textarea = document.createElement('textarea');
        textarea.value = editableResult; // 修改为 editableResult
        textarea.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
        document.body.appendChild(textarea);
        textarea.select();
        copySuccess = document.execCommand('copy');
        document.body.removeChild(textarea);
      } catch {
        // 静默失败
      }
    }

    // 最终降级方案
    if (!copySuccess) {
      const input = document.createElement('input');
      input.value = editableResult; // 修改为 editableResult
      input.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
      document.body.appendChild(input);
      input.select();
      setTimeout(() => document.body.removeChild(input), 100);
      alert(`文本已自动选中，请按 Ctrl+C 复制:\n\n${editableResult}`); // 修改为 editableResult
    }

    // 显示成功状态
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
    setError(''); // 清空错误状态
    
  } catch (e) {
    setError('复制失败，请手动选择文本复制');
  }
};

const handleCopyPureResult = async () => {
  try {
    if (!editablePureResult) return;  // 已更新为 editablePureResult

    let copySuccess = false;

    if (navigator.clipboard?.writeText) {
      try {
        await navigator.clipboard.writeText(editablePureResult); // 修改为 editablePureResult
        copySuccess = true;
      } catch {}
    }

    // 其他复制逻辑也需要更新为 editablePureResult
    if (!copySuccess) {
      try {
        const textarea = document.createElement('textarea');
        textarea.value = editablePureResult; // 修改为 editablePureResult
        textarea.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
        document.body.appendChild(textarea);
        textarea.select();
        copySuccess = document.execCommand('copy');
        document.body.removeChild(textarea);
      } catch {}
    }

    if (!copySuccess) {
      const input = document.createElement('input');
      input.value = editablePureResult; // 修改为 editablePureResult
      input.style.cssText = 'position:fixed;top:0;left:0;opacity:0;';
      document.body.appendChild(input);
      input.select();
      setTimeout(() => document.body.removeChild(input), 100);
      alert(`文本已自动选中，请按 Ctrl+C 复制:\n\n${editablePureResult}`); // 修改为 editablePureResult
    }

    setCopiedPure(true);
    setTimeout(() => setCopiedPure(false), 2000);
    setError('');
  } catch (e) {
    setError('复制失败，请手动选择文本复制');
  }
};

  const handleGenerate = async () => {
    const isDemoMode = !appId || !appSecret || !appToken || !tableId;
    const sdkAvailable = !!bitable?.base;

    setIsLoading(true);
    setError('');
    setResult('');

    try {
      let records: { record_id: string; fields: Record<string, string> }[] = [];

      if (sdkAvailable) {
        const { groupField } = parseTemplate(template);
        const fieldNames = extractFieldNamesFromTemplate(template);
        const table = await bitable.base.getActiveTable();
        const metas = await table.getFieldMetaList();
        const nameToId = new Map<string, string>();
        const nameToMeta = new Map<string, { id: string; name: string; type: number }>();
        metas.forEach((m: { id: string; name: string; type: number }) => {
          nameToId.set(m.name, m.id);
          nameToMeta.set(m.name, { id: m.id, name: m.name, type: m.type });
        });

        const envFieldId = nameToId.get('环境');
        const groupFieldId = nameToId.get(groupField);

        const resp = await table.getRecordList();

        console.log("metas:", metas);
        console.log("resp:", resp.toString());
        const sdkRecords = [];
        if (resp && typeof resp[Symbol.iterator] === 'function') {
          for (const record of resp) {
            sdkRecords.push(record);
          }
        }

        for (const r of sdkRecords) {
          const rid = r.recordId ?? r.id ?? r.record_id;
          if (envFieldId) {
            const envStr = await table.getCellString(envFieldId, rid);
            if (envStr !== '生产') continue;
          }

          const fieldsByName: Record<string, string> = {};
          if (groupFieldId) {
            const gv = await table.getCellString(groupFieldId, rid);
            fieldsByName[groupField] = gv;
          }
          for (const fname of fieldNames) {
            const fid = nameToId.get(fname);
            if (!fid) continue;
            const meta = nameToMeta.get(fname);
            if (meta && meta.type === FieldType.User) {
              const userField = await table.getFieldById(fid);
              // getValue 返回 IOpenUser[]
              const users = await (userField as any).getValue(rid);
              const ids = Array.isArray(users) ? users.map((u: any) => u.id).filter(Boolean) : [];
              const names = Array.isArray(users) ? users.map((u: any) => (u.name || u.enName || '')).filter(Boolean) : [];
              const personTags = ids.map((id: string) => `<person id='${id}' show_name=true show_avatar=false style='capsule'></person>`);
              fieldsByName[fname] = personTags.join('');
              fieldsByName[`${fname}__id`] = ids.join(',');
              fieldsByName[`${fname}__name`] = names.join('、');
            } else {
              const sv = await table.getCellString(fid, rid);
              fieldsByName[fname] = sv ?? '';
            }
          }
          records.push({ record_id: rid, fields: fieldsByName });
        }
      }

      // const filteredRecords = filterRecordsByEnvironment(records);

      if (records.length === 0) {
        setResult('没有找到环境为"生产"的数据');
        return;
      }

      const { groupField, template: templateFields, secondaryTemplate } = parseTemplate(template);
      const output = generateOutput(records, groupField, templateFields, secondaryTemplate);
      const plainOutput = generatePlainOutput(records, groupField, templateFields, secondaryTemplate);
      setResult(output);
      // 直接设置纯净版结果，不需要在useEffect中再次处理
      setPureResult(plainOutput);
      setEditablePureResult(plainOutput);
    } catch (err) {
      setError(err instanceof Error ? err.message : '生成结果时出错');
    } finally {
      setIsLoading(false);
      setHasGenerated(true);
    }
  };

  const isDemoMode = !appId || !appSecret || !appToken || !tableId;
  const sdkAvailable = !!bitable?.base;

  return (
    <div className="min-h-screen bg-gray-50 p-6">
      <div className="max-w-6xl mx-auto">
                
        <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
          {!
            sdkAvailable && (
              <div className="bg-white rounded-lg shadow-md p-6">
            <h2 className="text-xl font-semibold text-gray-800 mb-4">配置信息</h2>
            
            <div className="space-y-4">
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  App ID
                </label>
                <input
                  type="text"
                  value={appId}
                  onChange={(e) => setAppId(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入飞书应用的 App ID"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  App Secret
                </label>
                <input
                  type="password"
                  value={appSecret}
                  onChange={(e) => setAppSecret(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入飞书应用的 App Secret"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  App Token
                </label>
                <input
                  type="text"
                  value={appToken}
                  onChange={(e) => setAppToken(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入多维表格的 App Token"
                />
              </div>
              
              <div>
                <label className="block text-sm font-medium text-gray-700 mb-1">
                  Table ID
                </label>
                <input
                  type="text"
                  value={tableId}
                  onChange={(e) => setTableId(e.target.value)}
                  className="w-full px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500"
                  placeholder="请输入数据表的 Table ID"
                />
              </div>
            </div>
          </div>
            )
          }

          {/* Template Editor */}
          <div className="bg-white rounded-lg shadow-md p-6">
            
            <div className="space-y-4">
              <div>
                <div className="flex items-center justify-between mb-1">
                  <label className="text-xl font-semibold text-gray-800">
                    模板内容
                  </label>
                  <button
                    onClick={handleGenerate}
                    disabled={isLoading}
                    className="px-6 py-2 bg-blue-500 text-white font-medium rounded-md hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-400 disabled:opacity-50 disabled:cursor-not-allowed"
                  >
                    {isLoading ? '生成中...' : '生成结果'}
                  </button>
                </div>
                <textarea
                  value={template}
                  onChange={(e) => setTemplate(e.target.value)}
                  className="w-full h-40 px-3 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 font-mono text-sm"
                  placeholder="请输入模板内容"
                />
              </div>
              
              
            </div>
          </div>
        </div>

        {/* Version Tabs and Copy Button */}
        <div className="mt-8">
          <div className="flex flex-col items-center justify-center gap-4">
            {hasGenerated && (
              <div className="inline-flex rounded-md shadow-sm border border-gray-300 overflow-hidden">
                <button
                  onClick={() => setActiveTab('styled')}
                  className={`px-4 py-2 font-medium text-sm transition-colors duration-200 ${activeTab === 'styled' ? 'bg-blue-500 text-white' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  样式版
                </button>
                <button
                  onClick={() => setActiveTab('plain')}
                  className={`px-4 py-2 font-medium text-sm transition-colors duration-200 ${activeTab === 'plain' ? 'bg-blue-500 text-white' : 'bg-white text-gray-700 hover:bg-gray-50'}`}
                >
                  纯净版
                </button>
              </div>
            )}

            {/* 移除下面这个复制提示区域 */}
            {/* Copy Success Message */}
            {/* {hasGenerated && (
              <div className="flex items-center gap-2 mt-1">
                {copied && activeTab === 'styled' && <span className="text-green-600 text-sm">已复制样式版</span>}
                {copiedPure && activeTab === 'plain' && <span className="text-green-600 text-sm">已复制纯净版</span>}
              </div>
            )} */}
          </div>
        </div>

        {/* Error Message */}
        {error && (
          <div className="mt-4 p-4 bg-red-50 border border-red-200 rounded-md">
            <p className="text-red-800">{error}</p>
          </div>
        )}

        {/* Result with Single Preview */}
        {hasGenerated && (
          <div className="mt-8 bg-white rounded-lg shadow-md p-6">
            <div className="flex items-center justify-between mb-4">
              <h2 className="text-xl font-semibold text-gray-800">生成结果</h2>
              <div className="flex items-center gap-2">
                {(copied && activeTab === 'styled') && <span className="text-green-600 text-sm">已复制样式版</span>}
                {(copiedPure && activeTab === 'plain') && <span className="text-green-600 text-sm">已复制纯净版</span>}
                <button
                  onClick={activeTab === 'styled' ? handleCopyResult : handleCopyPureResult}
                  disabled={isLoading || (activeTab === 'styled' ? !editableResult : !editablePureResult)}
                  className="p-2 bg-blue-500 text-white rounded-md hover:bg-blue-600 focus:outline-none focus:ring-2 focus:ring-blue-400 disabled:opacity-50 disabled:cursor-not-allowed"
                  title="复制"
                >
                  <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <rect x="9" y="9" width="13" height="13" rx="2" ry="2"></rect>
                    <path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"></path>
                  </svg>
                </button>
              </div>
            </div>
            <div className="bg-gray-50 p-4 rounded-md">
              {/* 将 pre 标签替换为 textarea */}
              <textarea
                value={activeTab === 'styled' ? editableResult : editablePureResult}
                onChange={(e) => {
                  if (activeTab === 'styled') {
                    setEditableResult(e.target.value);
                  } else {
                    setEditablePureResult(e.target.value);
                  }
                }}
                className="w-full min-h-[300px] p-4 bg-white border border-gray-200 rounded-md font-mono text-sm text-gray-800 whitespace-pre-wrap resize-y"
              />
            </div>
          </div>
        )}

        
      </div>
    </div>
  );
};

export default FeishuPlugin;
