export interface TemplateField {
  name: string;
  type: 'field' | 'text';
}

export interface ParsedTemplate {
  groupField: string;
  template: TemplateField[];
  secondaryTemplate?: TemplateField[];
}

export function parseTemplate(template: string): ParsedTemplate {
  const lines = template.split('\n').filter(line => line.trim());
  if (lines.length < 2) {
    throw new Error('Template must have at least 2 lines');
  }

  const firstLineMatch = lines[0].match(/\[([^\]]+)\]/);
  if (!firstLineMatch) {
    throw new Error('First line must contain a field name in brackets');
  }
  const groupField = firstLineMatch[1];

  if (lines.length >= 3) {
    const secondaryTemplate = parseInlineTemplate(lines[1]);
    const itemTemplate = parseInlineTemplate(lines[2]);
    return { groupField, template: itemTemplate, secondaryTemplate };
  } else {
    const itemTemplate = parseInlineTemplate(lines[1]);
    return { groupField, template: itemTemplate };
  }
}

export function extractFieldNamesFromTemplate(template: string): string[] {
  const fieldNames: Set<string> = new Set();
  const matches = template.match(/\[([^\]]+)\]/g);
  
  if (matches) {
    matches.forEach(match => {
      const fieldName = match.slice(1, -1);
      fieldNames.add(fieldName);
    });
  }
  
  return Array.from(fieldNames);
}

// 检查记录是否有效（系统和项目名称不同时为空）
function isRecordValid(record: { record_id: string; fields: Record<string, string> }): boolean {
  const system = record.fields['系统'] || '';
  const projectName = record.fields['项目名称'] || '';
  // 如果系统和项目名称都为空，则记录无效
  return !(system === '' && projectName === '');
}

// 上线类型优先级映射
export const onlineTypePriority: Record<string, number> = {
  '提测需求': 1,
  '自测需求': 2,
  '自研优化': 3,
  '质量待办': 4,
  'BUG修复': 5
};

// 在generateOutput函数中添加排序逻辑（约第100-110行）
export function generateOutput(
  records: Array<{ record_id: string; fields: Record<string, string> }>,
  groupField: string,
  template: TemplateField[],
  secondaryTemplate?: TemplateField[]
): string {
  // 分类映射
  const categoryMap: Record<string, string> = {
    '新加坡': '海外战区',
    '欧洲': '海外战区',
    '北美': '海外战区',
    '全球中心': '海外全球',
    '全球中心（欧洲）': '海外全球',
    '国内': '国内'
  };
  
  const groups = new Map<string, Array<{ record_id: string; fields: Record<string, string> }>>();
  records.forEach(record => {
    if (isRecordValid(record)) {
      const originalGroupValue = record.fields[groupField];
      const mappedGroupValue = categoryMap[originalGroupValue] || originalGroupValue;
      if (!groups.has(mappedGroupValue)) groups.set(mappedGroupValue, []);
      groups.get(mappedGroupValue)!.push(record);
    }
  });

  const output: string[] = [];
  const order = ['国内', '海外全球', '海外战区'];
  const suffix: Record<string, string> = {
    '国内': '国内 22:00',
    '海外全球': '海外全球',
    '海外战区': '海外战区'
  };
  const getOrder = (value: string) => {
    if (groupField === '数据中心') {
      const idx = order.indexOf(value);
      return idx === -1 ? order.length : idx;
    }
    return 0;
  };
  const getDisplay = (value: string) => {
    if (groupField === '数据中心') return suffix[value] ?? value;
    return value;
  };
  const existingKeys = Array.from(groups.keys());
  const otherKeys = existingKeys.filter(k => !order.includes(k)).sort((a, b) => a.localeCompare(b));
  const displayKeys = [...order, ...otherKeys];

  if (secondaryTemplate && secondaryTemplate.length) {
    displayKeys.forEach((groupValue) => {
      const groupRecords = groups.get(groupValue) || [];
      output.push(`**${getDisplay(groupValue)}：**`);
      
      // 按上线类型排序记录
      const sortedRecords = [...groupRecords].sort((a, b) => {
        const typeA = (a.fields['上线类型'] || '').trim();
        const typeB = (b.fields['上线类型'] || '').trim();
        const priorityA = onlineTypePriority[typeA] || 999;
        const priorityB = onlineTypePriority[typeB] || 999;
        return priorityA - priorityB;
      });
      
      const secondaryMap = new Map<string, Array<{ record_id: string; fields: Record<string, string> }>>();
      
      sortedRecords.forEach(record => {
        // 生成分组键：[需求FLOW]+[任务内容]+[上线类型]
        const flow = (record.fields['需求FLOW'] || '').trim();
        const task = (record.fields['任务内容'] || '').trim();
        const onlineType = (record.fields['上线类型'] || '').trim();
        
        // 生成二级模板值
        const secVal = renderInline(record, secondaryTemplate);
        if (!secondaryMap.has(secVal)) secondaryMap.set(secVal, []);
        secondaryMap.get(secVal)!.push(record);
      });

      // 检查是否有有效的二级分组记录
      let hasValidRecords = false;
      secondaryMap.forEach((recordsInSec) => {
        recordsInSec.forEach((record) => {
          // 检查记录是否包含有效的字段值
          for (const field of template) {
            if (field.type === 'field' && record.fields[field.name]) {
              hasValidRecords = true;
              return;
            }
          }
        });
      });
      
      if (hasValidRecords) {
        const needsAggregate = template.some(t => t.type === 'field' && t.name === '系统')
          && template.some(t => t.type === 'field' && t.name === '项目名称')
          && template.some(t => t.type === 'field' && t.name === '开发负责人');
        let flowIndex = 1; // 在每个数据中心内部初始化序号计数器
        secondaryMap.forEach((recordsInSec, secVal) => {
          output.push(`  ${flowIndex}. ${secVal}`);
          flowIndex++;
          if (needsAggregate) {
            const lines = renderAggregatedBySystemDeveloper(recordsInSec, template);
            lines.forEach(line => output.push(`${line}`));
          } else {
            recordsInSec.forEach((record) => {
              const lineBody = renderInline(record, template);
              output.push(`${lineBody}`);
            });
          }
        });
      } else {
        // 没有有效记录时显示"无"
        output.push('- 无');
      }
      output.push('---');
      output.push(' ');
    });
  } else {
    displayKeys.forEach((groupValue) => {
      const groupRecords = groups.get(groupValue) || [];
      output.push(`**${getDisplay(groupValue)}：**`);
      
      // 按上线类型排序记录
      const sortedRecords = [...groupRecords].sort((a, b) => {
        const typeA = (a.fields['上线类型'] || '').trim();
        const typeB = (b.fields['上线类型'] || '').trim();
        const priorityA = onlineTypePriority[typeA] || 999;
        const priorityB = onlineTypePriority[typeB] || 999;
        return priorityA - priorityB;
      });
      
      // 直接使用所有排序后的记录，实现并集效果
      const uniqueRecords = sortedRecords;
      
      // 检查是否有有效的记录
      let hasValidRecords = false;
      uniqueRecords.forEach((record) => {
        // 检查记录是否包含有效的字段值
        for (const field of template) {
          if (field.type === 'field' && record.fields[field.name]) {
            hasValidRecords = true;
            return;
          }
        }
      });
      
      if (hasValidRecords) {
        const needsAggregate = template.some(t => t.type === 'field' && t.name === '系统')
          && template.some(t => t.type === 'field' && t.name === '项目名称')
          && template.some(t => t.type === 'field' && t.name === '开发负责人');
        if (needsAggregate) {
          const lines = renderAggregatedBySystemDeveloper(uniqueRecords, template);
          lines.forEach((line, idx) => output.push(`${idx + 1}. ${line}`));
        } else {
          uniqueRecords.forEach((record, index) => {
            const lineBody = renderInline(record, template);
            output.push(`${index + 1}. ${lineBody}`);
          });
        }
      } else {
        // 没有有效记录时显示"无"
        output.push('- 无');
      }
      output.push('---');
      output.push(' ');
    });
  }
  return output.join('\n');
}

export function parseInlineTemplate(template: string): TemplateField[] {
  const fields: TemplateField[] = [];
  let currentIndex = 0;
  while (currentIndex < template.length) {
    const fieldMatch = template.substring(currentIndex).match(/^\[([^\]]+)\]/);
    if (fieldMatch) {
      fields.push({ name: fieldMatch[1], type: 'field' });
      currentIndex += fieldMatch[0].length;
    } else {
      const nextBracket = template.indexOf('[', currentIndex);
      const textEnd = nextBracket === -1 ? template.length : nextBracket;
      const text = template.substring(currentIndex, textEnd);
      if (text) {
        fields.push({ name: text, type: 'text' });
      }
      currentIndex = textEnd;
    }
  }
  return fields;
}

// 上线类型颜色映射
export const onlineTypeColorMap: Record<string, string> = {
  '提测需求': 'blue',
  '自测需求': 'wathet',
  '自研优化': 'turquoise',
  '质量待办': 'yellow',
  'BUG修复': 'carmine'
};

export function renderInline(
  record: { record_id: string; fields: Record<string, string> },
  tokens: TemplateField[]
): string {
  let result = '';
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token.type === 'text') {
      const next = tokens[i + 1];
      const next2 = tokens[i + 2];
      const isOpeningTag = /<\s*text_tag[^>]*>/i.test(token.name);
      const isClosingTag = next2 && next2.type === 'text' && /<\s*\/\s*text_tag\s*>/i.test(next2.name);
      if (isOpeningTag && next && next.type === 'field' && next.name === '上线类型' && isClosingTag) {
        const fieldValue = (record.fields['上线类型'] || '').trim();
        const mapped = fieldValue && onlineTypeColorMap[fieldValue] ? onlineTypeColorMap[fieldValue] : '';
        result += mapped ? `<text_tag color='${mapped}'>${fieldValue}</text_tag>` : fieldValue;
        i += 2; // skip the field and closing tag
        continue;
      }
      if (token.name.includes('[上线类型]')) {
        const fieldValue = (record.fields['上线类型'] || '').trim();
        const mapped = fieldValue && onlineTypeColorMap[fieldValue] ? onlineTypeColorMap[fieldValue] : '';
        const replacement = mapped ? `<text_tag color='${mapped}'>${fieldValue}</text_tag>` : fieldValue;
        result += token.name.replace('[上线类型]', replacement);
      } else {
        result += token.name;
      }
    } else if (token.type === 'field') {
      const fieldValue = (record.fields[token.name] || '').trim();
      if (token.name === '开发负责人') {
        // 样式版仅输出人员标签或原文本，不附加人名
        if (fieldValue.startsWith('<person')) {
          result += fieldValue;
        } else {
          result += fieldValue;
        }
        continue;
      }
      if (token.name === '上线类型') {
        const mapped = fieldValue && onlineTypeColorMap[fieldValue] ? onlineTypeColorMap[fieldValue] : '';
        result += mapped ? `<text_tag color='${mapped}'>${fieldValue}</text_tag>` : fieldValue;
      } else if (token.name === '需求FLOW') {
        if (/^flow-(\d+)$/i.test(fieldValue)) {
          const match = fieldValue.match(/^flow-(\d+)$/i);
          const num = match ? match[1] : '';
          const displayText = `Flow-${num}`;
          const link = `https://ucp.yummy.tech/task/flow-${num}`;
          result += `<a href="${link}" target="_blank">${displayText}</a>`;
        } else if (fieldValue.startsWith('https://ucp.')) {
          const flowMatch = fieldValue.match(/Flow-(\d+)/i);
          if (flowMatch) {
            const num = flowMatch[1];
            const displayText = `Flow-${num}`;
            result += `<a href="${fieldValue}" target="_blank">${displayText}</a>`;
          } else {
            result += fieldValue;
          }
        } else {
          result += fieldValue;
        }
      } else {
        result += fieldValue;
      }
    }
  }
  return result;
}

function stripForPlain(input: string): string {
  let out = input || '';
  out = out.replace(/<\s*text_tag[^>]*>/gi, '');
  out = out.replace(/<\s*\/\s*text_tag\s*>/gi, '');
  out = out.replace(/<\s*a\b[^>]*>([\s\S]*?)<\s*\/\s*a\s*>/gi, '$1');
  out = out.replace(/<\s*font\b[^>]*>([\s\S]*?)<\s*\/\s*font\s*>/gi, '$1');
  out = out.replace(/<\s*person\b[^>]*><\s*\/\s*person\s*>/gi, '');
  out = out.replace(/\*\*/g, '');
  out = out.replace(/\*/g, '');
  out = out.replace(/__+/g, '');
  return out;
}

export function renderInlinePlain(
  record: { record_id: string; fields: Record<string, string> },
  tokens: TemplateField[]
): string {
  let result = '';
  for (let i = 0; i < tokens.length; i++) {
    const token = tokens[i];
    if (token.type === 'text') {
      result += stripForPlain(token.name);
    } else if (token.type === 'field') {
      const val = (record.fields[token.name] || '').trim();
      if (token.name === '开发负责人') {
        const name = (record.fields['开发负责人__name'] || '').trim();
        result += name || stripForPlain(val);
      } else if (token.name === '上线类型') {
        result += stripForPlain(val);
      } else if (token.name === '需求FLOW') {
        if (/^flow-(\d+)$/i.test(val)) {
          const m = val.match(/^flow-(\d+)$/i);
          const num = m ? m[1] : '';
          result += `Flow-${num}`;
        } else if (val.startsWith('https://ucp.')) {
          const m = val.match(/Flow-(\d+)/i);
          result += m ? `Flow-${m[1]}` : stripForPlain(val);
        } else {
          result += stripForPlain(val);
        }
      } else {
        result += stripForPlain(val);
      }
    }
  }
  return result;
}

// 修改renderAggregatedBySystemDeveloperPlain函数（纯净版）
function renderAggregatedBySystemDeveloperPlain(
  records: Array<{ record_id: string; fields: Record<string, string> }>,
  tokens: TemplateField[]
): string[] {
  const groups = new Map<string, { system: string; developerName: string; projects: string[] }>();
  records.forEach(r => {
    const system = (r.fields['系统'] || '').trim();
    const devName = (r.fields['开发负责人__name'] || '').trim();
    const proj = (r.fields['项目名称'] || '').trim();
    const key = `${system}||${devName}`;
    if (!groups.has(key)) {
      groups.set(key, { system, developerName: devName, projects: [] });
    }
    const g = groups.get(key)!;
    if (proj && !g.projects.includes(proj)) g.projects.push(proj);
  });

  const lines: string[] = [];
  // 按照系统字段排序（将Map转换为数组并排序）
  const sortedGroups = Array.from(groups.values()).sort((a, b) => {
    // 空字符串排在最后
    if (!a.system && !b.system) return 0;
    if (!a.system) return 1;
    if (!b.system) return -1;
    return a.system.localeCompare(b.system);
  });
  
  sortedGroups.forEach(g => {
    let result = '';
    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      if (token.type === 'field') {
        if (token.name === '系统') {
          result += g.system;
        } else if (token.name === '项目名称') {
          // 添加按字母排序
          result += g.projects.sort((a, b) => a.localeCompare(b)).join('、');
        } else if (token.name === '开发负责人') {
          result += g.developerName;
        } else {
          const first = records[0];
          result += stripForPlain((first?.fields[token.name] || '').trim());
        }
      } else {
        result += stripForPlain(token.name);
      }
    }
    lines.push(result);
  });
  return lines;
}

// 修改renderAggregatedBySystemDeveloper函数（样式版）
function renderAggregatedBySystemDeveloper(
  records: Array<{ record_id: string; fields: Record<string, string> }>,
  tokens: TemplateField[]
): string[] {
  const groups = new Map<string, { system: string; developerId: string; developerTag: string; developerName: string; projects: string[] }>();
  records.forEach(r => {
    const system = (r.fields['系统'] || '').trim();
    const devTag = (r.fields['开发负责人'] || '').trim();
    const devId = (r.fields['开发负责人__id'] || '').trim();
    const devName = (r.fields['开发负责人__name'] || '').trim();
    const proj = (r.fields['项目名称'] || '').trim();
    const key = `${system}||${devId || devName || devTag}`;
    if (!groups.has(key)) {
      groups.set(key, { system, developerId: devId, developerTag: devTag, developerName: devName, projects: [] });
    }
    const g = groups.get(key)!;
    if (proj && !g.projects.includes(proj)) g.projects.push(proj);
  });

  const lines: string[] = [];
  // 按照系统字段排序（将Map转换为数组并排序）
  const sortedGroups = Array.from(groups.values()).sort((a, b) => {
    // 空字符串排在最后
    if (!a.system && !b.system) return 0;
    if (!a.system) return 1;
    if (!b.system) return -1;
    return a.system.localeCompare(b.system);
  });
  
  sortedGroups.forEach(g => {
    let result = '';
    for (let i = 0; i < tokens.length; i++) {
      const token = tokens[i];
      if (token.type === 'field') {
        if (token.name === '系统') {
          result += g.system;
        } else if (token.name === '项目名称') {
          // 添加按字母排序
          result += g.projects.sort((a, b) => a.localeCompare(b)).join('、');
        } else if (token.name === '开发负责人') {
          const tag = g.developerTag;
          const name = g.developerName;
          // 样式版仅输出人员标签（如有），不追加姓名；无标签时回退到姓名
          if (tag) {
            result += tag;
          } else {
            result += name || '';
          }
        } else {
          const first = records[0];
          result += (first?.fields[token.name] || '').trim();
        }
      } else {
        result += token.name;
      }
    }
    lines.push(result);
  });
  return lines;
}

